CREATE TABLE IF NOT EXISTS "students" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(100) NOT NULL,
	"email" VARCHAR(100),
	"phone" VARCHAR(20),
	"emergency_phone" VARCHAR(20),
	"document" VARCHAR(255),
	"address" VARCHAR(200),
	"observations" VARCHAR(500),
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "users" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"username" VARCHAR(50) NOT NULL,
	"hashed_password" VARCHAR(200) NOT NULL,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "courses" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(100) NOT NULL,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "classes" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"course_id" INTEGER NOT NULL,
	"start_date" DATE NOT NULL,
	"end_date" DATE,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "student_classes" (
	"id" INTEGER NOT NULL,
	"student_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"class_id" INTEGER NOT NULL,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "roll_call" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"classe_id" INTEGER NOT NULL,
	"week_start" DATE NOT NULL,
	"week_end" DATE NOT NULL,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "student_roll_call" (
	"id" INTEGER NOT NULL,
	"student_class_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"roll_call_id" INTEGER NOT NULL,
	"presence" BOOLEAN NOT NULL,
	PRIMARY KEY("id")
);



ALTER TABLE "classes"
ADD FOREIGN KEY("course_id") REFERENCES "courses"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "student_classes"
ADD FOREIGN KEY("student_id") REFERENCES "students"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "student_classes"
ADD FOREIGN KEY("class_id") REFERENCES "classes"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "roll_call"
ADD FOREIGN KEY("classe_id") REFERENCES "classes"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "student_roll_call"
ADD FOREIGN KEY("roll_call_id") REFERENCES "roll_call"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "student_roll_call"
ADD FOREIGN KEY("student_class_id") REFERENCES "student_classes"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;